INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('96beaa23-56e3-54d2-95dd-338d6d10c8ec', '2ff64012-1f25-5b8a-aefc-6b0394e80399', 'en', $h$IBC Oil System Without Hose Reel – IBC3045$h$, $h$ibc-oil-system-without-hose-reel-ibc3045$h$, NULL, $h$<div> <div><p><strong>Why the IBC3045 IBC Oil System Without Hose Reel?</strong></p><p>We designed IBC oil systems to make work easier for businesses with high-capacity oil needs. You can use different combinations in the system; you can choose oil dispensing guns with or without meters and pneumatic pumps with different delivery rates.</p><p><a href="https://www.gulersan.com/wp-content/uploads/2021/01/IBC3045-3.jpg"><img alt="IBC Oil System Without Hose Reel IBC3045. Reel-free, high-pressure pneumatic pump system for oil transfer from IBC tanks, designed for industrial bulk oil dispensing." src="https://www.gulersan.com/wp-content/uploads/2021/01/IBC3045-3.jpg"/></a></p></div> </div>$h$, NULL, $h$IBC Oil System Without Hose Reel – IBC3045 | HD Marine$h$, $h$Why the IBC3045 IBC Oil System Without Hose Reel? We designed IBC oil systems to make work easier for businesses with high-capacity oil needs. You can use…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f6972329-319b-5f2c-bad9-403e2c528c19', 'b26f9cd1-2280-5aff-82c8-6a32b3400848', 'en', $h$Plastic Funnels – PH$h$, $h$plastic-funnels-ph$h$, NULL, $h$<div> <div><p><strong>Why the PH Plastic Funnel?</strong></p><p>Sturdy plastic body designed for comfortable use, with an ergonomic handle. Suitable for transferring motor oil, diesel, gasoline, lubricants, and water.</p></div> </div>$h$, NULL, $h$Plastic Funnels – PH | HD Marine$h$, $h$Why the PH Plastic Funnel? Sturdy plastic body designed for comfortable use, with an ergonomic handle. Suitable for transferring motor oil, diesel…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('a78bbeab-8d4f-5a57-b555-f1d11bb1eed9', 'b0889d07-4daf-5d6c-b16a-bbb8eb10c9a9', 'en', $h$Pneumatic Oil Drainer Tank Heavy Duty 80 Lt – 4295$h$, $h$pneumatic-oil-drainer-tank-heavy-duty-80-lt-4295$h$, NULL, $h$<div> <div><p><strong>Why the 4295 Heavy Duty Pneumatic Oil Drainer?</strong></p><p>With the pneumatic telescopic oil drainer you collect waste oil drained from the engine and gearbox. With this telescopic oil tank you can collect oil without lifting vehicles off the ground. Slide the telescopic arms under the vehicle and drain the oil into the pan. From there, draw the oil into the tank with the help of air. The pan includes a grate that prevents oil splashing. You can track the amount of used oil on the tank scale. The unit offers an 80-liter usable tank capacity. Two fixed and two swivel casters give it high mobility. You discharge the waste oil in the tank with air. The safety valve on the tank provides protection against excessive air pressure. Do not use it with corrosive or flammable liquids.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Drainer Tank Heavy Duty 80 Lt – 4295 | HD Marine$h$, $h$Why the 4295 Heavy Duty Pneumatic Oil Drainer? With the pneumatic telescopic oil drainer you collect waste oil drained from the engine and gearbox. With…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('6c149b56-c209-5a67-83eb-3022eb84a2e9', '3a9f01b3-d473-52b1-9bee-4531a32ce242', 'en', $h$Pneumatic Oil Drainer Tank with Gauge 80 Lt – 42909$h$, $h$pneumatic-oil-drainer-tank-with-gauge-80-lt-42909$h$, NULL, $h$<div> <div><p><strong>Why the 42909 Pneumatic Oil Drainer with Gauge?</strong></p><p>The new-generation pneumatic oil drainer tank with gauge is designed for collecting waste oil drained from the engine and gearbox. Thanks to the telescopic funnel, it is used by raising the vehicle on a lift and removing the drain plug; the glass chamber on the funnel and the scale on it let you see the amount of waste oil collected and record it easily. It has an 80 Lt tank and a 9 Lt chamber capacity. With two fixed and two swivel casters, its mobility is high. The waste oil inside the tank is discharged with air. The safety valve on the tank provides protection against excessive air pressure. It must not be used with corrosive or flammable liquids.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Drainer Tank with Gauge 80 Lt – 42909 | HD Marine$h$, $h$Why the 42909 Pneumatic Oil Drainer with Gauge? The new-generation pneumatic oil drainer tank with gauge is designed for collecting waste oil drained from…$h$, 'auto') ON CONFLICT DO NOTHING;
