INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('2490ff11-6c52-5d90-877b-3f0f46a1a1b6', '52d6278b-6ea6-53dc-b5ba-b0408f9330d4', 'en', $h$Oil Drain Bucket 50 Lt – 4250$h$, $h$oil-drain-bucket-50-lt-4250$h$, NULL, $h$<div> <div><p><strong>Why the 4250 Oil Drain Bucket?</strong></p><p>With the oil drain bucket you collect waste oil drained from the engine and gearbox. The bucket offers a 50-liter storage capacity. Thanks to its telescopic funnel, you raise the vehicle on a lift and use the bucket after removing the drain plug. Four swivel casters give it high mobility. You discharge the waste oil in the tank manually. Do not use it with corrosive or flammable liquids. We designed it for locations without intensive use. It provides easy transport and is an economical model.</p></div> </div>$h$, NULL, $h$Oil Drain Bucket 50 Lt – 4250 | HD Marine$h$, $h$Why the 4250 Oil Drain Bucket? With the oil drain bucket you collect waste oil drained from the engine and gearbox. The bucket offers a 50-liter storage…$h$, 'auto') ON CONFLICT DO NOTHING;
