INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e2bf292a-2acc-59fb-ac44-5d0381fe5cd3', 'b366bf85-d795-5a94-9a10-5878479fbc51', 'en', $h$Plastic Measuring Jugs – LKP$h$, $h$plastic-measuring-jugs-lkp$h$, NULL, $h$<div> <p><strong>Why the LKP Plastic Measuring Jug?</strong></p><p>Both liter and gallon scales. Durable plastic for professional use.</p><div> </div><div><div><img alt="Plastic measuring jugs. Measuring containers used for precise measurement and safe transfer of oils, fluids, and chemicals." src="https://www.gulersan.com/wp-content/uploads/2021/03/litre-kablari.jpg"/></div></div> </div>$h$, NULL, $h$Plastic Measuring Jugs – LKP | HD Marine$h$, $h$Why the LKP Plastic Measuring Jug? Both liter and gallon scales. Durable plastic for professional use.$h$, 'auto') ON CONFLICT DO NOTHING;
