INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('343024a7-0267-53b9-a048-f1c9e9f2e155', 'ad597699-80c1-53e3-a91f-7b4660c8a4fb', 'en', $h$Metal Funnels – HN$h$, $h$metal-funnels-hn$h$, NULL, $h$<div> <div><p><strong>Why the HN Metal Funnel?</strong></p><p>Sturdy metal body designed for comfortable use, with an ergonomic handle. Suitable for transferring motor oil, diesel, gasoline, lubricants, and water.</p></div> </div>$h$, NULL, $h$Metal Funnels – HN | HD Marine$h$, $h$Why the HN Metal Funnel? Sturdy metal body designed for comfortable use, with an ergonomic handle. Suitable for transferring motor oil, diesel, gasoline…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('d08524a2-4b35-54d8-a215-c966d7baee55', 'e23a45e8-b936-57e7-b3fb-d019ae6564a4', 'en', $h$Graco Compatible Spare Parts$h$, $h$graco-compatible-spare-parts$h$, $h$Aro® Compatible Spare Parts$h$, $h$<div> <div><p>Aro® first launched its air-operated double diaphragm pump in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and one of the leading AODD Pump brands.</p></div> </div><div> <div><p>ARO® air-operated diaphragm pumps have the capacity to transfer a wide range of viscous fluids and ensure stall-free, ice-free operation. The unbalanced air valve design prevents the stalling problems associated with other pumps. Quick-dump exhaust valves direct cold exhaust air away from ice-prone components and prevent freezing. Depending on the type of fluid to be transferred, piston pump packages are available with multiple configurations for the pump section, including single-body, two-body, or heavy-duty two-body designs.</p><p>With their cost-effectiveness and reliable construction, ARO® diaphragm pumps are a good choice for industrial and chemical applications. The bolted, leak-free design eliminates cross-contamination and increases operator safety. The modular structure, reduced part count, and easy-to-use repair kits also minimize product repair time when needed.</p><p>HD Marine brings you reliable, high-quality spare parts compatible with double diaphragm (AODD) pumps. HD Marine provides replacement product support for many parts of your choice and is the place to find Aro spare parts such as <strong>valve balls, valve seats, diaphragms, gaskets, clamp bands, mufflers, pistons, and valve rings</strong>.</p><p>In the event of any failure or maintenance of your diaphragm pumps, you can select products suitable for the Aro brand individually on the HD Marine site, or from the <strong>Aro Service Kits</strong> section you can access service/repair kits that bring together screws, gaskets, and many types of rings. Service kits come in two types: a wet kit for the wet end of your pneumatic double diaphragm pump, and a kit used for the maintenance and repair of the air side of your air-operated double diaphragm pump. Since these two kits contain different products, you should make your choice by considering which products you need and in which area you will use them.</p><p>If you prefer to purchase products individually rather than the <strong>Aro Service Kits</strong>, you can also find <strong>Aro gaskets, Aro rings, Aro valve balls, Aro valve seats, Aro hardware, and Aro diaphragms</strong>. However, it should be kept in mind that the area in which each industry uses its pumps, and the Aro spare part suitable for that area, will vary. Based on your specific application needs such as chemical compatibility, temperature, and sealing capacity, HD Marine offers its customers the most widely used and preferred quality materials and products in pump parts, such as <strong>Santopren, Hytrel, N-fit, PTFE, Neopren</strong>.</p></div> </div>$h$, NULL, $h$Graco Compatible Spare Parts | HD Marine$h$, $h$Aro® first launched its air-operated double diaphragm pump in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('99f86537-7cd4-5ba6-b432-8413b7bb9082', '2f042790-8ffd-550e-a331-f0a748541f63', 'en', $h$Pneumatic Stationary Oil Drum System – DVS4500$h$, $h$pneumatic-stationary-oil-drum-system-dvs4500$h$, NULL, $h$<div> <div><p><strong>Why the DVS4500 Pneumatic Stationary Oil Drum System?</strong></p><p>Stationary oil drum systems are available in many versions for different purposes. Pump options with different delivery rates and pressure ratios, hose lengths of up to 20 meters, and liter-counting metered dispensing guns that can be adapted to any desired system give it a very high working capability. Considering the differing needs of every business, these systems offer an excellent solution for companies. Oil drum systems consist of 5 standard components,<br/>but you can choose your own oil pump, oil dispensing gun, and oil hose reel.</p></div> </div>$h$, NULL, $h$Pneumatic Stationary Oil Drum System – DVS4500 | HD Marine$h$, $h$Why the DVS4500 Pneumatic Stationary Oil Drum System? Stationary oil drum systems are available in many versions for different purposes. Pump options with…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('3bc27962-6df6-5602-9acb-2a4f322d2840', 'b9bbc9fa-3e1a-5f18-86b8-0d34a9cda087', 'en', $h$Pneumatic Stationary Grease Drum System – DVS2500$h$, $h$pneumatic-stationary-grease-drum-system-dvs2500$h$, NULL, $h$<div> <div><p><strong>Why the DVS2500 Pneumatic Stationary Grease Drum System?</strong></p><p>Wall-mounted stationary grease drum systems are available in different versions. Thanks to pump options with different delivery rates and pressure ratios, hose reels with hose lengths of up to 20 meters, and products such as a metered grease gun that can be adapted to the system when desired, the system has a high working capability. Considering the differing needs of every business, these systems offer an excellent solution for companies. Grease drum systems consist of 9 standard components, but you can choose your own grease pump, grease gun, and grease hose length.</p></div> </div>$h$, NULL, $h$Pneumatic Stationary Grease Drum System – DVS2500 | HD Marine$h$, $h$Why the DVS2500 Pneumatic Stationary Grease Drum System? Wall-mounted stationary grease drum systems are available in different versions. Thanks to pump…$h$, 'auto') ON CONFLICT DO NOTHING;
