INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f726f874-63b4-5d8f-bf60-2991db593bdd', '30c18689-490f-5330-986d-a98c46aba1a3', 'en', $h$Pneumatic Oil Pump Drum Type 5:1 12 Lt – 4400$h$, $h$pneumatic-oil-pump-drum-type-51-12-lt-4400$h$, NULL, $h$<div> <div><p><strong>Why the 4400 Drum Type Pneumatic Oil Pump?</strong></p><p>The drum type pneumatic oil pump with a 5:1 pressure ratio transfers low, medium, and high viscosity oils over medium and long distances. The delivery rate of the pneumatic oil pump varies according to different applications and combinations. The pressure of the supplied air and the viscosity and temperature of the fluid affect it. Hose and connection sizes and the gun type also determine the delivery rate. The operating pressure ranges from a minimum of 6 bar to a maximum of 8 bar. Use filtered and lubricated air to increase the performance and service life of the air-operated drum type oil pump. The piston diameter is Ø75 mm. Optional accessories enhance its functionality.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Pump Drum Type 5:1 12 Lt – 4400 | HD Marine$h$, $h$Why the 4400 Drum Type Pneumatic Oil Pump? The drum type pneumatic oil pump with a 5:1 pressure ratio transfers low, medium, and high viscosity oils over…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('3dd48f0c-d62a-5bff-98ea-490c32959f3a', '48e4559c-bd7b-5661-9709-90f3619cb490', 'en', $h$Pneumatic Oil Pump 80 Lt – 4200$h$, $h$pneumatic-oil-pump-80-lt-4200$h$, NULL, $h$<div> <div><p><strong>Why the 4200 Pneumatic Oil Pump?</strong></p><p>The pneumatic light oil pump offers an ideal combination option for oil refilling in all kinds of working environments (transmission, differential, engine, machinery). It has a 3:1 pressure ratio; it transfers low, medium, and high viscosity oils over medium and long distances. The operating pressure ranges from a minimum of 6 bar to a maximum of 8 bar. Use filtered and lubricated air to increase the performance and service life of pneumatic oil pumps. The piston diameter is Ø62 mm. Optional accessories enhance its functionality.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Pump 80 Lt – 4200 | HD Marine$h$, $h$Why the 4200 Pneumatic Oil Pump? The pneumatic light oil pump offers an ideal combination option for oil refilling in all kinds of working environments…$h$, 'auto') ON CONFLICT DO NOTHING;
