INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('625fe650-50c6-57b6-81a6-1ca850351668', 'cd9d6475-c8ff-5456-a906-2f287a806488', 'en', $h$Pneumatic Oil Pump Wall Type 3:1 22 Lt – 3046$h$, $h$pneumatic-oil-pump-wall-type-31-22-lt-3046$h$, NULL, $h$<div> <div><p><strong>Why the 3046 Wall Type Pneumatic Oil Pump?</strong></p><p>The pneumatic oil pump with a 3:1 pressure ratio transfers low, medium, and high viscosity oils. You can use it for short, medium, and long distance transfers. Pump delivery varies according to several factors. For example, the pressure of the supplied air and the viscosity and temperature of the fluid have an effect. Hose and connection sizes and the gun type used also determine pump delivery. The operating pressure ranges from a minimum of 6 bar to a maximum of 8 bar. Use filtered and lubricated air to increase the pump’s performance and service life. The piston diameter is Ø62 mm. You can easily mount it on the wall with the Model 7120 wall bracket. Or you can also install it on an IBC tank.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Pump Wall Type 3:1 22 Lt – 3046 | HD Marine$h$, $h$Why the 3046 Wall Type Pneumatic Oil Pump? The pneumatic oil pump with a 3:1 pressure ratio transfers low, medium, and high viscosity oils. You can use it…$h$, 'auto') ON CONFLICT DO NOTHING;
